import sys
from math import factorial

def is_lucky(x):
    s = str(x)
    for c in s:
        if c not in {'4', '7'}:
            return False
    return True

def generate_kth_permutation(n, k):
    if k > factorial(n):
        return None
    numbers = list(range(1, n+1))
    perm = []
    k -= 1  # convert to 0-based
    while numbers:
        f = factorial(len(numbers)-1)
        index = k // f
        perm.append(numbers.pop(index))
        k %= f
    return perm

def main():
    n, k = map(int, sys.stdin.readline().split())
    if n <= 20:
        perm = generate_kth_permutation(n, k)
        if perm is None:
            print(-1)
            return
        count = 0
        for i in range(1, n+1):
            if is_lucky(i) and is_lucky(perm[i-1]):
                count += 1
        print(count)
    else:
        # For n > 20, the permutation is same as initial for first n-20 elements
        # Generate the last 20 elements' permutation
        m = 20
        perm_last = generate_kth_permutation(m, k)
        if perm_last is None:
            print(-1)
            return
        # The permutation is [1, 2, ..., n-m] followed by perm_last
        # Check positions in the last m elements
