    s = str(x)
    for c in s:
        if c not in {'4', '7'}:
            return False
    return True

def generate_lucky_numbers(limit):
    lucky = []
    from collections import deque
    queue = deque(['4', '7'])
    while queue:
        num_str = queue.popleft()
        num = int(num_str)
        if num <= limit:
            lucky.append(num)
            queue.append(num_str + '4')
            queue.append(num_str + '7')
    return lucky

def main():
    n, k = map(int, sys.stdin.readline().split())

    # Find the maximum m where m! <= k
    m = 1
    while True:
        if factorial(m) >= k:
            break
        m += 1

    if m > n:
        print(-1)
        return

    # Generate the k-th permutation of the last m elements
    elements = list(range(n - m + 1, n + 1))
    perm = []
    current_k = k - 1  # 0-based index
    elements_copy = elements.copy()
    for i in range(m):
        fact = factorial(m - 1 - i)
        index = current_k // fact
        perm.append(elements_copy[index])
        del elements_copy[index]
        current_k %= fact

    # The permutation array is [1..n-m] followed by perm
    # Now count the lucky positions
    lucky_numbers = generate_lucky_numbers(n)
    count = 0
    for num in lucky_numbers:
        if num <= n - m:
            # Position num is in the first part, value is num
            if is_lucky(num):
                count += 1
        else:
            # Position num is in the perm part
            pos_in_perm = num - (n - m) - 1
            if pos_in_perm < len(perm):
                val = perm[pos_in_perm]
                if is_lucky(val):
                    count += 1
    print(count)

def factorial(x):
    if x == 0:
        return 1
    res = 1
    for i in range(1, x+1):
        res *= i
    return res

